<?php use App\Support\App;$u=App::requireAuth();$title='Support';require __DIR__.'/../layouts/head.php';?><div class="flex"><?php require __DIR__.'/../components/sidebar.php';?><main class="p-8 flex-1"><h1 class="text-2xl font-semibold">Support Tickets</h1><form id="ticket" class="saas-card p-6 mt-6 max-w-xl"><input type="hidden" id="csrf" value="<?=App::csrf()?>"><input class="field" name="subject" placeholder="Subject" required><textarea class="field mt-3" name="message" required></textarea><button class="btn btn-dark mt-3">Create ticket</button></form></main></div><script>ticket.onsubmit=async e=>{e.preventDefault();let r=await fetch('/api/tickets',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf.value},body:JSON.stringify(Object.fromEntries(new FormData(ticket)))});Swal.fire(JSON.stringify(await r.json()))}</script><?php require __DIR__.'/../layouts/foot.php';?>